CREATE OR REPLACE FUNCTION public.save_my_ideahire_onboarding_profile(p_role_preference text, p_freelancer_categories text[] DEFAULT '{}'::text[], p_client_categories text[] DEFAULT '{}'::text[], p_onboarding_goals text[] DEFAULT '{}'::text[], p_specialty_summary text DEFAULT NULL::text, p_project_readiness text DEFAULT NULL::text, p_onboarding_action text DEFAULT 'complete'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_allowed_categories constant text[] := array[
    'Programowanie',
    'Grafika i design',
    'Marketing',
    'Copywriting',
    'Video',
    'Fotografia',
    'AI i automatyzacje',
    'Dane, analizy i research',
    'Biznes i e-commerce',
    'Architektura, wnętrza i CAD'
  ];
  v_allowed_goals constant text[] := array[
    'first_project',
    'more_orders',
    'offer_service',
    'build_portfolio',
    'find_specialist',
    'publish_project',
    'compare_options',
    'explore_platform'
  ];
  v_role text := nullif(trim(p_role_preference), '');
  v_freelancer_categories text[] := coalesce(p_freelancer_categories, '{}'::text[]);
  v_client_categories text[] := coalesce(p_client_categories, '{}'::text[]);
  v_goals text[] := coalesce(p_onboarding_goals, '{}'::text[]);
  v_summary text := nullif(regexp_replace(trim(coalesce(p_specialty_summary, '')), '\\s+', ' ', 'g'), '');
  v_readiness text := nullif(trim(coalesce(p_project_readiness, '')), '');
  v_action text := coalesce(nullif(trim(p_onboarding_action), ''), 'complete');
  v_row public.ideahire_onboarding_profiles%rowtype;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Zaloguj się, aby zapisać ustawienia konta.';
  end if;

  if v_role not in ('find_work', 'hire_talent', 'both') then
    raise exception using
      errcode = '22023',
      message = 'Wybierz prawidłowy sposób korzystania z IdeaHire.';
  end if;

  if v_action not in ('complete', 'skip') then
    raise exception using
      errcode = '22023',
      message = 'Nieprawidłowa akcja onboardingu.';
  end if;

  if cardinality(v_freelancer_categories) > 3
     or cardinality(v_client_categories) > 3 then
    raise exception using
      errcode = '22023',
      message = 'W każdej sekcji możesz wybrać maksymalnie 3 kategorie.';
  end if;

  if exists (
    select 1
    from unnest(v_freelancer_categories || v_client_categories) item
    where item <> all(v_allowed_categories)
  ) then
    raise exception using
      errcode = '22023',
      message = 'Wybrano kategorię, której IdeaHire nie obsługuje.';
  end if;

  if cardinality(v_goals) > 3 then
    raise exception using
      errcode = '22023',
      message = 'Możesz wybrać maksymalnie 3 cele.';
  end if;

  if exists (
    select 1
    from unnest(v_goals) item
    where item <> all(v_allowed_goals)
  ) then
    raise exception using
      errcode = '22023',
      message = 'Wybrano nieprawidłowy cel.';
  end if;

  if v_summary is not null and char_length(v_summary) > 160 then
    raise exception using
      errcode = '22001',
      message = 'Opis specjalizacji może mieć maksymalnie 160 znaków.';
  end if;

  if v_readiness is not null
     and v_readiness not in ('exploring', 'idea', 'brief_ready', 'urgent') then
    raise exception using
      errcode = '22023',
      message = 'Wybierz prawidłowy etap projektu.';
  end if;

  if v_action = 'complete' then
    if v_role in ('find_work', 'both')
       and cardinality(v_freelancer_categories) = 0 then
      raise exception using
        errcode = '22023',
        message = 'Wybierz co najmniej jedną kategorię, w której chcesz działać.';
    end if;

    if v_role in ('hire_talent', 'both')
       and cardinality(v_client_categories) = 0 then
      raise exception using
        errcode = '22023',
        message = 'Wybierz co najmniej jedną kategorię, w której szukasz pomocy.';
    end if;

    if cardinality(v_goals) = 0 then
      raise exception using
        errcode = '22023',
        message = 'Wybierz co najmniej jeden cel na początek.';
    end if;

    if v_role in ('hire_talent', 'both') and v_readiness is null then
      raise exception using
        errcode = '22023',
        message = 'Określ, na jakim etapie jest Twój projekt.';
    end if;
  end if;

  insert into public.ideahire_onboarding_profiles (
    user_id,
    role_preference,
    freelancer_categories,
    client_categories,
    onboarding_goals,
    specialty_summary,
    project_readiness,
    personalization_profile_version,
    completed_at,
    skipped_at
  ) values (
    v_user_id,
    v_role,
    v_freelancer_categories,
    v_client_categories,
    v_goals,
    v_summary,
    v_readiness,
    2,
    case when v_action = 'complete' then now() else null end,
    case when v_action = 'skip' then now() else null end
  )
  on conflict (user_id) do update set
    role_preference = excluded.role_preference,
    freelancer_categories = excluded.freelancer_categories,
    client_categories = excluded.client_categories,
    onboarding_goals = excluded.onboarding_goals,
    specialty_summary = excluded.specialty_summary,
    project_readiness = excluded.project_readiness,
    personalization_profile_version = 2,
    completed_at = case
      when v_action = 'complete' then now()
      else ideahire_onboarding_profiles.completed_at
    end,
    skipped_at = case
      when v_action = 'complete' then null
      else now()
    end;

  select p.*
  into v_row
  from public.ideahire_onboarding_profiles p
  where p.user_id = v_user_id;

  return jsonb_build_object(
    'authenticated', true,
    'needs_onboarding', false,
    'role_preference', v_row.role_preference,
    'freelancer_categories', to_jsonb(v_row.freelancer_categories),
    'client_categories', to_jsonb(v_row.client_categories),
    'onboarding_goals', to_jsonb(v_row.onboarding_goals),
    'specialty_summary', v_row.specialty_summary,
    'project_readiness', v_row.project_readiness,
    'profile_version', v_row.personalization_profile_version,
    'completed_at', v_row.completed_at,
    'skipped_at', v_row.skipped_at,
    'updated_at', v_row.updated_at
  );
end;
$function$

