CREATE OR REPLACE FUNCTION public.ideahire_set_job_listing_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.budget_negotiable := coalesce(new.budget_negotiable, false);
    new.listing_duration_days := coalesce(new.listing_duration_days, 14);

    if new.listing_duration_days not in (7, 14, 30) then
      raise exception 'Czas publikacji musi wynosić 7, 14 albo 30 dni.'
        using errcode = '23514';
    end if;

    new.expires_at :=
      coalesce(new.created_at, statement_timestamp())
      + make_interval(days => new.listing_duration_days::integer);

    return new;
  end if;

  -- Warunki publikacji wybieramy tylko podczas dodawania zlecenia.
  -- Jeżeli kontrolowana procedura republikuje wpis przez zmianę created_at,
  -- termin zostanie policzony ponownie z zachowaniem pierwotnego okresu.
  if new.created_at is distinct from old.created_at then
    new.budget_negotiable := old.budget_negotiable;
    new.listing_duration_days := old.listing_duration_days;
    new.expires_at :=
      new.created_at
      + make_interval(days => old.listing_duration_days::integer);
  else
    new.budget_negotiable := old.budget_negotiable;
    new.listing_duration_days := old.listing_duration_days;
    new.expires_at := old.expires_at;
  end if;

  return new;
end;
$function$

