CREATE OR REPLACE FUNCTION public.ideahire_require_full_account_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_age_status text;
  v_account_status text;
begin
  if v_user_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if public.is_ideahire_staff(
    v_user_id,
    array['owner', 'admin']::text[]
  ) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if public.ideahire_has_active_restriction(v_user_id) then
    raise exception using
      errcode = 'P0001',
      message = 'Konto jest zawieszone. Szczegóły decyzji i możliwość odwołania znajdziesz w statusie konta.';
  end if;

  select lifecycle_row.status
  into v_account_status
  from public.ideahire_account_lifecycle lifecycle_row
  where lifecycle_row.user_id = v_user_id;

  if v_account_status in (
    'data_minimized',
    'closure_pending',
    'closed'
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'To konto jest objęte zakończonym lub wykonywanym procesem usunięcia danych i nie może wykonywać nowych operacji.';
  end if;

  v_age_status := public.ideahire_age_access_status(v_user_id);

  if v_age_status = 'age_required' then
    raise exception using
      errcode = 'P0001',
      message = 'Uzupełnij datę urodzenia, aby korzystać z tej funkcji.';
  end if;

  if v_age_status = 'under_16' then
    raise exception using
      errcode = 'P0001',
      message = 'Konto IdeaHire jest dostępne od ukończenia 16 lat.';
  end if;

  if v_age_status = 'minor_limited' then
    raise exception using
      errcode = 'P0001',
      message = 'Ta funkcja jest dostępna wyłącznie dla pełnych kont 18+.';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
